/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
for n in [2,3,6,7,8,9,10,11,16,18]:
    print('\\nPAGE',n)
    links=[]
    for a in r.pages[n-1].get('/Annots',[]):
        a=a.get_object()
        act=a.get('/A',{})
        if act.get('/URI'):
            u=str(act['/URI'])
            if ('github' in u or 'readthedocs' in u or 'rtfd' in u) and u not in links:
                links.append(u)
    if n==7:
        print('Linked artifact count',len(links))
        print('\\n'.join(links[:8]))
        print('\\n'.join(u for u in links if 'fep' in u or 'cocma' in u))
    else:
        print('\\n'.join(links))
PY"
